import React, { useState, useMemo, useEffect, useContext } from 'react';
import { StaffRolesContext } from '../StaffRolesContext'; // Ensure this path is correct

// --- Helper Components (Toast, Modal, Icons) ---

const Toast = ({ message, type, onHide }) => {
    useEffect(() => {
        const timer = setTimeout(onHide, 3000);
        return () => clearTimeout(timer);
    }, [onHide]);
    const toastStyle = {
        position: 'fixed', top: '20px', right: '20px', padding: '1rem 1.5rem',
        borderRadius: '8px', color: 'white', zIndex: 1050,
        backgroundColor: type === 'success' ? '#28a745' : '#dc3545',
        boxShadow: '0 4px 15px rgba(0,0,0,0.2)',
    };
    return <div style={toastStyle}>{message}</div>;
};

const Modal = ({ isOpen, onClose, onConfirm, title, children }) => {
    if (!isOpen) return null;
    return (
        <div style={styles.modalOverlay} onClick={onClose}>
            <div style={styles.modalContent} onClick={e => e.stopPropagation()}>
                <h4>{title}</h4>
                <p>{children}</p>
                <div style={styles.modalFooter}>
                    <button style={styles.modalButtonSecondary} onClick={onClose}>Cancel</button>
                    <button style={styles.modalButtonDanger} onClick={onConfirm}>Confirm</button>
                </div>
            </div>
        </div>
    );
};

const InfoIcon = () => (
    <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" style={{ color: '#6c757d', marginTop: '2px' }}><circle cx="12" cy="12" r="10"></circle><line x1="12" y1="16" x2="12" y2="12"></line><line x1="12" y1="8" x2="12.01" y2="8"></line></svg>
);
const EditIcon = () => (<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7" /><path d="M18.5 2.5a2.121 2.121 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" /></svg>);
const DeleteIcon = () => (<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="3 6 5 6 21 6" /><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" /></svg>);


const ActivityAllocationTab = ({ term, onAllocationChange }) => {
    const { definedRoles: staffRoles } = useContext(StaffRolesContext);

    const [activities, setActivities] = useState([
        { id: 1, activityName: 'Tutorial', numberOfGroups: 5, maxGroupSize: 25, weeklyClassTime: 2, justification: '', distribution: {} },
        { id: 2, activityName: 'Practical', numberOfGroups: '', maxGroupSize: '', weeklyClassTime: '', justification: '', distribution: {} },
        { id: 3, activityName: 'Lab', numberOfGroups: '', maxGroupSize: '', weeklyClassTime: '', justification: '', distribution: {} },
    ]);

    const [activeActivityId, setActiveActivityId] = useState(1);
    const [editingActivity, setEditingActivity] = useState({ id: null, name: '' });
    const [activityToDelete, setActivityToDelete] = useState(null);
    const [toast, setToast] = useState({ show: false, message: '', type: '' });

    const staffColumns = useMemo(() => {
        const rolesFromContext = staffRoles || [];
        return ['Subject Coordinator', ...rolesFromContext.map(r => r.name)];
    }, [staffRoles]);

    const calculatedData = useMemo(() => {
        const termMultiplier = term === 'Autumn' ? 1.0 : 0.923;
        let grandTotal = 0;
        const activityDetails = activities.map(activity => {
            const numGroups = Number(activity.numberOfGroups) || 0;
            const classTime = Number(activity.weeklyClassTime) || 0;
            const allocation = numGroups * classTime * termMultiplier * 0.0125;
            grandTotal += allocation;

            const distributionSum = Object.values(activity.distribution || {}).reduce(
                (total, tasks) => total + Object.values(tasks).reduce((sum, val) => sum + (val || 0), 0), 0
            );
            return { id: activity.id, allocation, isDistributionInvalid: distributionSum > 0.0125 };
        });
        return { grandTotal, activityDetails };
    }, [activities, term]);

    useEffect(() => {
        onAllocationChange?.(calculatedData.grandTotal);
    }, [calculatedData.grandTotal, onAllocationChange]);

    const showToast = (message, type = 'success') => setToast({ show: true, message, type });

    const handleInputChange = (id, field, value) => {
        // Validation for numeric inputs
        if (['numberOfGroups', 'maxGroupSize', 'weeklyClassTime'].includes(field)) {
            if (value && parseFloat(value) < 0) {
                showToast('Value cannot be negative.', 'error');
                return;
            }
        }
        setActivities(prev => prev.map(act => act.id === id ? { ...act, [field]: value } : act));
    };

    const handleDistributionChange = (id, role, task, inputValue) => {
        const numericValue = parseFloat(inputValue.replace(/%/g, '')) || 0;
        if (numericValue < 0) {
            showToast('Allocation cannot be negative.', 'error');
            return;
        }
        setActivities(prev => prev.map(act => {
            if (act.id !== id) return act;
            const newDistribution = { ...act.distribution };
            if (!newDistribution[role]) newDistribution[role] = {};
            newDistribution[role][task] = numericValue / 100;
            return { ...act, distribution: newDistribution };
        }));
    };

    const handleAddActivity = () => {
        const newId = activities.length > 0 ? Math.max(...activities.map(a => a.id)) + 1 : 1;
        const newActivity = {
            id: newId, activityName: `New Activity`, numberOfGroups: '', maxGroupSize: '', weeklyClassTime: '', distribution: {}
        };
        setActivities(prev => [...prev, newActivity]);
        setActiveActivityId(newId);
        setEditingActivity({ id: newId, name: 'New Activity' }); // Immediately enter edit mode
    };

    const handleEditClick = (activity) => setEditingActivity({ id: activity.id, name: activity.activityName });

    const handleUpdateActivityName = () => {
        if (!editingActivity.name.trim()) {
            showToast("Activity name cannot be blank.", 'error');
            return;
        }
        setActivities(prev => prev.map(act => act.id === editingActivity.id ? { ...act, activityName: editingActivity.name.trim() } : act));
        setEditingActivity({ id: null, name: '' });
        showToast("Activity updated successfully!");
    };

    const confirmDelete = (id) => {
        const newActivities = activities.filter(a => a.id !== id);
        setActivities(newActivities);
        if (activeActivityId === id) {
            setActiveActivityId(newActivities.length > 0 ? newActivities[0].id : null);
        }
        setActivityToDelete(null);
        showToast("Activity deleted successfully!");
    };

    const handleSaveAll = () => {
        // Check for any invalid distributions before saving
        const hasInvalid = calculatedData.activityDetails.some(a => a.isDistributionInvalid);
        if (hasInvalid) {
            showToast("Cannot save. One or more activities have an invalid allocation distribution (>1.25%).", "error");
            return;
        }
        showToast("All activities saved successfully!");
    };

    const activeActivity = activities.find(a => a.id === activeActivityId);
    const activeActivityDetails = activeActivity ? calculatedData.activityDetails.find(a => a.id === activeActivity.id) : null;

    return (
        <>
            {toast.show && <Toast message={toast.message} type={toast.type} onHide={() => setToast({ show: false })} />}
            <Modal
                isOpen={activityToDelete !== null}
                onClose={() => setActivityToDelete(null)}
                onConfirm={() => confirmDelete(activityToDelete)}
                title="Confirm Deletion"
            >
                Are you sure you want to delete this activity? This action cannot be undone.
            </Modal>

            <div style={styles.container}>
                <div style={styles.header}>
                    <div style={styles.titleContainer}><h3 style={styles.title}>Activity Allocation</h3><InfoIcon /></div>
                    <button style={styles.addButton} onClick={handleAddActivity}>+ Add</button>
                </div>

                <div style={styles.activityTabsContainer}>
                    {activities.map(activity => (
                        <div key={activity.id} style={styles.activityTabWrapper}>
                            <button
                                style={{ ...styles.activityTab, ...(activity.id === activeActivityId ? styles.activityTabActive : {}) }}
                                onClick={() => setActiveActivityId(activity.id)}
                            >
                                {editingActivity.id === activity.id ? (
                                    <input
                                        type="text"
                                        value={editingActivity.name}
                                        onChange={(e) => setEditingActivity({ ...editingActivity, name: e.target.value })}
                                        style={styles.tabInput}
                                        autoFocus
                                    />
                                ) : (
                                    activity.activityName
                                )}
                            </button>
                            <div style={styles.tabActions}>
                                {editingActivity.id === activity.id ? (
                                    <>
                                        <button onClick={handleUpdateActivityName} style={styles.iconButton}>✓</button>
                                        <button onClick={() => setEditingActivity({ id: null, name: '' })} style={styles.iconButton}>✕</button>
                                    </>
                                ) : (
                                    <>
                                        <button onClick={() => handleEditClick(activity)} style={styles.iconButton}><EditIcon /></button>
                                        <button onClick={() => setActivityToDelete(activity.id)} style={styles.iconButton}><DeleteIcon /></button>
                                    </>
                                )}
                            </div>
                        </div>
                    ))}
                </div>

                <div style={styles.contentBody}>
                    {activeActivity && (
                        <>
                            <div style={styles.inputGrid}>
                                <div><label style={styles.label}>{`${activeActivity.activityName} Allocation`}</label><input style={styles.inputReadOnly} type="text" readOnly value={`${(activeActivityDetails?.allocation * 100).toFixed(1)}%`} /></div>
                                <div><label style={styles.label}>Number of groups</label><input style={styles.input} type="number" min="0" value={activeActivity.numberOfGroups} onChange={(e) => handleInputChange(activeActivity.id, 'numberOfGroups', e.target.value)} /></div>
                                <div><label style={styles.label}>Max group size</label><input style={styles.input} type="number" min="0" value={activeActivity.maxGroupSize} onChange={(e) => handleInputChange(activeActivity.id, 'maxGroupSize', e.target.value)} /></div>
                                <div><label style={styles.label}>Weekly class time (hours)</label><input style={styles.input} type="number" min="0" step="0.5" value={activeActivity.weeklyClassTime} onChange={(e) => handleInputChange(activeActivity.id, 'weeklyClassTime', e.target.value)} /></div>
                            </div>

                            <hr style={styles.hr} />

                            <h4 style={styles.subHeader}>Allocation per weekly hour per group</h4>
                            {activeActivityDetails?.isDistributionInvalid && <p style={styles.errorMessage}>Maximum allocation per weekly hour exceeded. The sum must not be more than 1.25%.</p>}

                            <table style={styles.table}>
                                <thead>
                                    <tr>
                                        <th style={{...styles.th, textAlign: 'right'}}>Preparation / Setup</th>
                                        <th style={{...styles.th, textAlign: 'right'}}>Delivery / Supervision</th>
                                    </tr>
                                </thead>
                                <tbody>
                                    {staffColumns.map(role => {
                                        const prepValue = activeActivity.distribution?.[role]?.['Preparation / Setup'] || 0;
                                        const deliveryValue = activeActivity.distribution?.[role]?.['Delivery / Supervision'] || 0;
                                        return (
                                            <tr key={role}>
                                                <td style={styles.td}>{role}</td>
                                                <td style={{...styles.td, width: '20%'}}>
                                                    <input type="text" style={styles.tableInput} value={`${(prepValue * 100).toFixed(1)}%`} onChange={(e) => handleDistributionChange(activeActivity.id, role, 'Preparation / Setup', e.target.value)} />
                                                </td>
                                                <td style={{...styles.td, width: '20%'}}>
                                                    <input type="text" style={styles.tableInput} value={`${(deliveryValue * 100).toFixed(1)}%`} onChange={(e) => handleDistributionChange(activeActivity.id, role, 'Delivery / Supervision', e.target.value)} />
                                                </td>
                                            </tr>
                                        );
                                    })}
                                </tbody>
                            </table>
                        </>
                    )}
                </div>

                <div style={styles.footer}><button style={styles.saveButton} onClick={handleSaveAll}>💾 Save</button></div>
            </div>
        </>
    );
};


